data.variablesTransform:
{
	"payload": {
		"update": (
			$ids := $merge($keys($).{ $ & "Id": $lookup($$, $).id });
			$omitKeys := $.$sift(function($v, $k) { $not($isObject($v)) and $k != "customerId" });
			$merge([$omitKeys, $ids])
      /*loops over all data from form and writes only
      the selected ids, omitting the objects from
      the mutation transform*/
		),
		"where": { "id": $state.context.REQUEST.DATA.id }
	}
}

