data.query:
query Query($where: SalesOrderStatusWhereInput, $orderBy: [SalesOrderStatusOrderByInput!], $first: Int, $after: String) {
  salesOrderStatus(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        active
        cancelled
        closed
        default
        extDefault
        hold
        open
        system
        usable
        color
        externalId
        message
        customData
      }
    }
  }
}

